import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String inputStr = scanner.next();
        StringBuilder outputStr = new StringBuilder();
        boolean insertedAtFlag = false;
        int idx = 0;
        while (idx < inputStr.length()) {
            if (idx + 3 <= inputStr.length() && inputStr.substring(idx, idx + 3).equals("dot")) {
                outputStr.append('.');
                idx += 3;
            } else if (idx + 2 <= inputStr.length() && inputStr.substring(idx, idx + 2).equals("at") && !insertedAtFlag && idx != 0) {
                outputStr.append('@');
                idx += 2;
                insertedAtFlag = true;
            } else {
                outputStr.append(inputStr.charAt(idx));
                idx++;
            }
        }
        for (int j = 0; j < outputStr.length(); j++) {
            char ch = outputStr.charAt(j);
            if (j == 0 && ch == '.') {
                System.out.print("dot");
            } else if (j == 0 && ch == '@') {
                System.out.print("at");
            } else if (j == outputStr.length() - 1 && outputStr.charAt(outputStr.length() - 1) == '@') {
                System.out.print("at");
            } else if (j == outputStr.length() - 1 && outputStr.charAt(outputStr.length() - 1) == '.') {
                System.out.print("dot");
            } else {
                System.out.print(ch);
            }
        }
        System.out.println();
        scanner.close();
    }
}
